fix_code:
public static void main(String[] args) {

	Scanner sc = new Scanner(System.in);

	long N = sc.nextLong();
	boolean judge = true;

	List<Long> C = new ArrayList<Long>();

	for (long i = 1; i < 1000000; i++) {

		C.add(i*i*i);
	}

	for (int i = C.size()-1; i >= 0; i--) {
		if (C.get(i) > N) {
			continue; // Continue to the next iteration instead of breaking out of the loop
		}

		String S = Long.toString(C.get(i));
		int L = S.length();
		boolean isPalindrome = true;

		for (int j = 0; j < L / 2; j++) {
			if (S.charAt(j) != S.charAt(L - j - 1)) {
				isPalindrome = false;
				break;
			}
		}

		if (isPalindrome) {
			System.out.println(C.get(i));
			break;
		}
	}
	sc.close();

}

